class UserLocalDatasource extends UserDataSource {
  UserLocalDatasource(this.storageService);

  final StorageService storageService;

  @override
  String get storageKey => USER_LOCAL_STORAGE_KEY;

  @override
  Future<Either<AppException, User>> fetchUser() async {
    final data = await storageService.get(storageKey);
    if (data == null) {
      return Left(
        AppException(
          identifier: 'UserLocalDatasource',
          statusCode: 404,
          message: 'User not found',
        ),
      );
    }
    final userJson = jsonDecode(data.toString());

    return Right(User.fromJson(userJson));
  }

class FileStorage implements TodosRepository {
  final String tag;
  final Future<Directory> Function() getDirectory;

  const FileStorage(
    this.tag,
    this.getDirectory,
  );

  @override
  Future<List<TodoEntity>> loadTodos() async {
    final file = await _getLocalFile();
    final string = await file.readAsString();
    final json = JsonDecoder().convert(string);
    final todos = (json['todos'])
        .map<TodoEntity>((todo) => TodoEntity.fromJson(todo))
        .toList();

    return todos;
  }

class KeyValueStorage implements TodosRepository {
  final String key;
  final SharedPreferences sharedPreferences;
  final JsonCodec codec;

  const KeyValueStorage(this.key, this.sharedPreferences, [this.codec = json]);

  @override
  Future<List<TodoEntity>> loadTodos() async {
    final todos = sharedPreferences.getString(key);

    if (todos == null) {
      throw Exception('No todos found for key: $key');
    }

    return codec
        .decode(todos)['todos']
        .cast<Map<String, dynamic>>()
        .map<TodoEntity>(TodoEntity.fromJson)
        .toList(growable: false);
  }

class TodoEntity {
  final bool complete;
  final String id;
  final String note;
  final String task;

  TodoEntity(this.task, this.id, this.note, this.complete);

  @override
  int get hashCode =>
      complete.hashCode ^ task.hashCode ^ note.hashCode ^ id.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is TodoEntity &&
          runtimeType == other.runtimeType &&
          complete == other.complete &&
          task == other.task &&
          note == other.note &&
          id == other.id;

  Map<String, Object> toJson() {
    return {
      'complete': complete,
      'task': task,
      'note': note,
      'id': id,
    };
  }

class MyTextInputControl with TextInputControl {
  TextEditingValue _editingState = .empty;
  final ValueNotifier<bool> _visible = ValueNotifier<bool>(false);

  /// The input control's visibility state for updating the visual presentation.
  ValueListenable<bool> get visible => _visible;

  /// Register the input control.
  void register() => TextInput.setInputControl(this);

  /// Restore the original platform input control.
  void unregister() => TextInput.restorePlatformInputControl();

  @override
  void show() => _visible.value = true;

  @override
  void hide() => _visible.value = false;

  @override
  void setEditingState(TextEditingValue value) => _editingState = value;

  /// Process user input.
  ///
  /// Updates the internal editing state by inserting the input text,
  /// and by replacing the current selection if any.
  void processUserInput(String input) {
    _editingState = _editingState.copyWith(
      text: _insertText(input),
      selection: _replaceSelection(input),
    );

    // Request the attached client to update accordingly.
    TextInput.updateEditingValue(_editingState);
  }

class Insets extends UniqueWidget<InsetsState> {
  const Insets() : super(key: const GlobalObjectKey<InsetsState>('insets'));

  @override
  InsetsState createState() => InsetsState();
}

class InsetsState extends State<Insets> {
  static InsetsState get instance => const Insets().currentState!;

  EdgeInsets insets = const .fromLTRB(8, 25, 8, 12);
  void changeInset(Inset inset, double value) {
    setState(() {
      insets = switch (inset) {
        Inset.top => insets.copyWith(top: value),
        Inset.sides => insets.copyWith(left: value, right: value),
        Inset.bottom => insets.copyWith(bottom: value),
      };
    });
  }

  final Set<Toggle> _togglers = <Toggle>{};
  void toggle(Toggle toggler, bool value) {
    setState(() {
      value ? _togglers.add(toggler) : _togglers.remove(toggler);
    });
  }

  @override
  Widget build(BuildContext context) {
    final Widget topNotch = ClipRRect(
      borderRadius: .vertical(bottom: Radius.circular(insets.top)),
      child: SizedBox(
        height: insets.top,
        child: const FractionallySizedBox(
          widthFactor: 1 / 2,
          child: ColoredBox(color: Colors.black),
        ),
      ),
    );
    final Widget bottomIndicator = SizedBox(
      width: double.infinity,
      height: insets.bottom,
      child: const FractionallySizedBox(
        heightFactor: 0.5,
        widthFactor: 0.5,
        child: PhysicalShape(
          clipper: ShapeBorderClipper(shape: StadiumBorder()),
          color: Color(0xC0000000),
          child: SizedBox.expand(),
        ),
      ),
    );
    final Widget sideBar = SizedBox(
      width: insets.left,
      height: double.infinity,
      child: const IgnorePointer(child: ColoredBox(color: Colors.black12)),
    );

    final Widget app = _ToggleModel(
      togglers: _togglers,
      child: Builder(
        builder: (BuildContext context) => MediaQuery(
          data: MediaQuery.of(context).copyWith(
            viewInsets: EdgeInsets.only(top: insets.top),
            viewPadding: insets,
            padding: insets,
          ),
          child: const SafeAreaExampleApp(),
        ),
      ),
    );

    return _InsetModel(
      insets: insets,
      child: Directionality(
        textDirection: .ltr,
        child: Stack(
          children: <Widget>[
            app,
            Align(alignment: .topCenter, child: topNotch),
            Align(alignment: .bottomCenter, child: bottomIndicator),
            Align(alignment: .centerLeft, child: sideBar),
            Align(alignment: .centerRight, child: sideBar),
          ],
        ),
      ),
    );
  }
}

